def compute(payload):
    """保留批次和行序，为每条记录生成清理首尾空白并转小写的邮箱。"""
    return [
        [record["email"].strip().lower() for record in batch]
        for batch in payload["batches"]
    ]

def compute(payload):
    """保留批次和行序，返回 name,city,source,time 对象；姓名与城市的空白折叠为单个空格。"""
    result = []
    for batch in payload["batches"]:
        out_batch = []
        for rec in batch:
            out_batch.append({
                "name": " ".join(rec["name"].split()),
                "city": " ".join(rec["city"].split()),
                "source": rec["source"],
                "time": rec["time"],
            })
        result.append(out_batch)
    return result

import json
import unittest
from pathlib import Path

import sys
sys.path.insert(0, str(Path(__file__).resolve().parents[3]))

from components.contact_keys.work import compute


class TestContactKeys(unittest.TestCase):
    def test_normalizes_and_preserves_order(self):
        payload = {
            "batches": [
                [
                    {"email": " A@EXAMPLE.COM ", "name": "Alice", "city": "", "source": "web", "time": 8},
                    {"email": "b@x.com", "name": "Bob", "city": "NY", "source": "cli", "time": 9},
                ],
                [
                    {"email": "  C@Y.ORG  ", "name": "C", "city": "", "source": "web", "time": 10},
                ],
            ]
        }
        result = compute(payload)
        self.assertEqual(
            result,
            [["a@example.com", "b@x.com"], ["c@y.org"]],
        )

    def test_empty_batches(self):
        self.assertEqual(compute({"batches": []}), [])


if __name__ == "__main__":
    unittest.main()

